function coreDescDefsSvg(){ return CORE_DESC_SVG_DEFS; }
function coreDescMeta(index){ return CORE_DESC_META[String(index).padStart(3,"0")] || null; }
function coreDescName(index){
  const m = coreDescMeta(index); if (!m) return "";
  return (typeof state !== "undefined" && state.lang === "ru") ? (m.ru || m.en) : m.en;
}
function coreDescUse(index, x, y, w, h, title){
  if (!index) return "";
  const ttl = title ? `<title>${esc(title)}</title>` : "";
  return `<use href="#cds-${String(index).padStart(3,"0")}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="xMidYMid meet">${ttl}</use>`;
}
/* Horizontal overlays (thin interbeds / bed contacts) must span the
   complete lithology band width. The source legend symbols are horizontal
   swatches, so stretching them into the exact grain-size-controlled band
   width is intentional here; point glyphs continue to use coreDescUse(). */
function coreDescUseFill(index, x, y, w, h, title){
  if (!index) return "";
  const ttl = title ? `<title>${esc(title)}</title>` : "";
  return `<use href="#cds-${String(index).padStart(3,"0")}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="none">${ttl}</use>`;
}
function coreDescSwatch(index, w=96, h=32){
  if(!index) return "";
  const id=String(index).padStart(3,"0");
  return `<svg class="vp-swatch" viewBox="0 0 ${w} ${h}" aria-hidden="true"><rect width="${w}" height="${h}" fill="#fff"/><use href="#cds-${id}" x="2" y="2" width="${w-4}" height="${h-4}" preserveAspectRatio="xMidYMid meet"/><rect width="${w}" height="${h}" fill="none" stroke="var(--struct-ink,#1F2328)" stroke-width=".5"/></svg>`;
}

