  K1al:"#99DE80", K1ap:"#99DE80", K1br:"#80DE4D", K1h:"#80DE4D",
  K1v:"#80DE4D",  K1b:"#80DE4D",

  Jurassic:"#66FF99", J:"#66FF99",
  "Upper Jurassic":"#B2FFB2", "Middle Jurassic":"#80FF99", "Lower Jurassic":"#4DFF80",
  Tithonian:"#CCFFCC",   Kimmeridgian:"#B2FFB2", Oxfordian:"#B2FFB2",
  Callovian:"#80FF99",  Bathonian:"#80FF99",   Bajocian:"#80FF99",
  "Upper Bajocian":"#80FF99", "Lower Bajocian":"#80FF99",
  Aalenian:"#80FF99",
  Toarcian:"#4DFF80",   Pliensbachian:"#4DFF80", Sinemurian:"#4DFF80", Hettangian:"#4DFF80",
  J3:"#B2FFB2", J2:"#80FF99", J1:"#4DFF80",
  J3t:"#CCFFCC", J3km:"#B2FFB2", J3o:"#B2FFB2",
