  Cisuralian:"#80FFDE", "Lower Permian":"#80FFDE",
  Kungurian:"#80FFDE", Artinskian:"#4DFFDE", Sakmarian:"#4DFFDE", Asselian:"#4DFFDE",
  P3:"#B2FFFF", P2:"#99FFEB", P1:"#80FFDE",

  Carboniferous:"#66CCFF", C:"#66CCFF",
  Pennsylvanian:"#66CCFF", "Upper Carboniferous":"#66CCFF",
  Gzhelian:"#99EBFF",  Kasimovian:"#80DEFF",
  Moscovian:"#66DEEB", Bashkirian:"#4DCCEB",
  Mississippian:"#99B2DE", "Lower Carboniferous":"#99B2DE",
  Serpukhovian:"#CCDEEB", Visean:"#99CCEB", Tournaisian:"#80B2DE",
  C3:"#80DEFF", C2:"#4DCCEB", C1:"#99B2DE",

  Devonian:"#8099FF", D:"#8099FF",
  "Upper Devonian":"#B2B2FF", "Middle Devonian":"#9999FF", "Lower Devonian":"#6680FF",
  Famennian:"#CCCCFF", Frasnian:"#B2B2FF",
  Givetian:"#9999FF", Eifelian:"#9999FF",
  Emsian:"#6680FF",   Pragian:"#6680FF", Lochkovian:"#6680FF",
  D3:"#B2B2FF", D2:"#9999FF", D1:"#6680FF",

  Silurian:"#B280FF", S:"#B280FF",
  Pridoli:"#EBCCFF", Ludlow:"#CCB2FF",
  Wenlock:"#B299EB", Llandovery:"#9966FF",
  S2:"#CCB2FF", S1:"#9966FF",

  Ordovician:"#FF80DE", O:"#FF80DE",
  "Upper Ordovician":"#FFB2DE", "Middle Ordovician":"#FF99DE", "Lower Ordovician":"#EB80DE",
  O3:"#FFB2DE", O2:"#FF99DE", O1:"#EB80DE",

  Cambrian:"#FF8099", Cm:"#FF8099",
  Furongian:"#FFCCCC",
