/* Linear-interpolate the MIS/paleotemp curve at the given age (Ma).
   Returns °C; clamps to curve endpoints for out-of-range ages.
   Mirrors eustaticAtAge() so the two tracks share the same
   age-driven plumbing. */
function tempAtAge(ageMa){
  if (!Number.isFinite(ageMa)) return null;
  const c = MIS_TEMP_CURVE;
  if (ageMa <= c[0].age) return c[0].t;
  if (ageMa >= c[c.length-1].age) return c[c.length-1].t;
  for (let i=1;i<c.length;i++){
    if (ageMa <= c[i].age){
      const p = c[i-1], q = c[i];
      const f = (ageMa - p.age) / (q.age - p.age);
      return p.t + f*(q.t - p.t);
    }
  }
  return null;
}

/* Parse a 6-digit hex colour string into [r,g,b]. Used by tempColor()
   when interpolating the temperature ramp; falls back to mid-grey if
   the input doesn't parse cleanly. */
function _hexToRgb(hex){
  const h = String(hex||"").trim().replace(/^#/, "");
  if (h.length !== 6) return [128,128,128];
  return [
    parseInt(h.slice(0,2), 16),
    parseInt(h.slice(2,4), 16),
    parseInt(h.slice(4,6), 16),
  ];
}

/* Map a temperature (°C) to a colour along the cold→hot ramp defined
   by --temp-cold / --temp-cool / --temp-mid / --temp-warm / --temp-hot.
   Anchor temperatures span 5 °C (frozen) → 30 °C (Cretaceous hothouse),
   matching the SC.temp scale range. Used for both the pill stroke and
   the step-line so the colour itself carries the temperature signal at
   a glance — no need to read the number.

   Results are memoised at 0.1 °C resolution. drawMIS calls tempColor
   for every interval band, every step line, every pill, and every
   header gradient slice — for a curve with ~40 intervals that's
   140+ calls per render, all converging on a small set of distinct
   temperatures. The Map.get() lookup is much faster than re-running
   the 5-stop interpolation and 5 cssVar reads. */
const _tempColorCache = new Map();
function tempColor(t){
  if (!Number.isFinite(t)) return cssVar("--ink-soft") || "#777";
  const key = Math.round(t * 10);
  const cached = _tempColorCache.get(key);
  if (cached !== undefined) return cached;
  const stops = [
    {t:5,  c:cssVar("--temp-cold")},
    {t:12, c:cssVar("--temp-cool")},
    {t:18, c:cssVar("--temp-mid")},
    {t:24, c:cssVar("--temp-warm")},
    {t:30, c:cssVar("--temp-hot")},
  ];
  let result;
  if (t <= stops[0].t) result = stops[0].c;
  else if (t >= stops[stops.length-1].t) result = stops[stops.length-1].c;
  else {
    for (let i=1;i<stops.length;i++){
      if (t <= stops[i].t){
        const p = stops[i-1], q = stops[i];
        const f = (t - p.t) / (q.t - p.t);
        const a = _hexToRgb(p.c), b = _hexToRgb(q.c);
        const r = Math.round(a[0] + f*(b[0]-a[0]));
        const g = Math.round(a[1] + f*(b[1]-a[1]));
        const bl= Math.round(a[2] + f*(b[2]-a[2]));
        result = `rgb(${r},${g},${bl})`;
        break;
      }
    }
    if (!result) result = stops[stops.length-1].c;
  }
  _tempColorCache.set(key, result);
  return result;
}

/* Pick a representative age for a depth d, using available data:
     1. Geochronology measurements that bracket d (linear interp on
        midpoints).
     2. Stratigraphy interval midpoint via STAGE_AGE_MA.
   Returns null if neither source can place this depth. */
function ageAtDepth(d){
  // Geochron pass — find two flanking measured ages and interpolate
  // by depth midpoint of each interval.
  const gPts = (state.geochron||[])
    .filter(g => g.age != null && Number.isFinite(g.top) && Number.isFinite(g.base))
    .map(g => ({d:(g.top+g.base)/2, age:g.age}))
    .sort((a,b)=>a.d-b.d);
  if (gPts.length === 1) return gPts[0].age;
  if (gPts.length >= 2){
    if (d <= gPts[0].d) return gPts[0].age;
    if (d >= gPts[gPts.length-1].d) return gPts[gPts.length-1].age;
    for (let i=1;i<gPts.length;i++){
      if (d <= gPts[i].d){
        const p = gPts[i-1], q = gPts[i];
        const f = (d - p.d) / (q.d - p.d);
        return p.age + f*(q.age - p.age);
      }
    }
  }
  // Stratigraphy pass — find interval containing d, use stage/system age midpoint
  for (const s of (state.stratigraphy||[])){
    if (d >= s.top && d <= s.base){
      const a = STAGE_AGE_MA[s.stage] || STAGE_AGE_MA[s.system];
      if (a) return (a.top + a.base) / 2;
    }
  }
  return null;
}

/* ===================================================================
   FACIES CODE REFERENCE
   ------------------------------------------------------------------
   The most widely-used short codes for clastic / carbonate / turbidite
   facies. Shown in the DepositionalEnv editor as a quick-reference
   table so the user doesn't have to remember whether Sp means
   "planar-bedded sand" or "planar cross-bedded sand".
     • Miall 1985/1996 — fluvial / alluvial (G*, S*, F*, P, C)
     • Walker 1992 — marine shelf / shoreface
     • Bouma 1962 — turbidite divisions (Ta–Te)
     • Reading 1996 — carbonate platform
   =================================================================== */
const FACIES_CODES = Object.freeze([
  // === Miall fluvial (gravel) ===
  {code:"Gmm", name:"Matrix-supported massive gravel",  group:"Fluvial (Miall)", desc:"Debris-flow deposit"},
  {code:"Gcm", name:"Clast-supported massive gravel",   group:"Fluvial (Miall)", desc:"Pseudoplastic debris flow"},
  {code:"Gh",  name:"Crudely horizontally-bedded gravel", group:"Fluvial (Miall)", desc:"Longitudinal bars, lag deposits"},
  {code:"Gp",  name:"Planar cross-bedded gravel",        group:"Fluvial (Miall)", desc:"Transverse bars, bar growth"},
  {code:"Gt",  name:"Trough cross-bedded gravel",        group:"Fluvial (Miall)", desc:"Minor channel-fills"},
  // === Miall fluvial (sand) ===
  {code:"Sm",  name:"Massive sand",                      group:"Fluvial (Miall)", desc:"Rapid deposition, hyperconcentrated flow"},
  {code:"Sh",  name:"Horizontal-laminated sand",         group:"Fluvial (Miall)", desc:"Upper flow regime, plane bed"},
  {code:"Sl",  name:"Low-angle (<15°) cross-bedded sand", group:"Fluvial (Miall)", desc:"Scour fills, antidunes"},
  {code:"Sp",  name:"Planar cross-bedded sand",          group:"Fluvial (Miall)", desc:"Transverse / linguoid bars (2D dunes)"},
  {code:"St",  name:"Trough cross-bedded sand",          group:"Fluvial (Miall)", desc:"3D dunes — sinuous/lunate crested"},
  {code:"Sr",  name:"Ripple cross-laminated sand",       group:"Fluvial (Miall)", desc:"Lower flow regime ripples"},
  {code:"Ss",  name:"Scour-fill broad shallow",          group:"Fluvial (Miall)", desc:"Scour, channel fills"},
  // === Miall fluvial (fines + special) ===
  {code:"Fl",  name:"Laminated mud / silt / very fine sand", group:"Fluvial (Miall)", desc:"Overbank, abandoned channel"},
  {code:"Fm",  name:"Massive mud / silt",                group:"Fluvial (Miall)", desc:"Overbank / drape, suspension fall-out"},
  {code:"Fr",  name:"Rooted mud",                        group:"Fluvial (Miall)", desc:"Pedogenic alteration"},
  {code:"C",   name:"Coal / carbonaceous mud",           group:"Fluvial (Miall)", desc:"Mire, swamp"},
  {code:"P",   name:"Paleosol / pedogenic carbonate",    group:"Fluvial (Miall)", desc:"Calcic / argillic horizon"},
  // === Walker shoreface / shelf ===
  {code:"HCS", name:"Hummocky cross-stratified sand",    group:"Marine (Walker)", desc:"Storm-wave reworking, lower shoreface — offshore transition"},
  {code:"SCS", name:"Swaley cross-stratified sand",      group:"Marine (Walker)", desc:"Amalgamated storm beds, middle shoreface"},
  {code:"Sw",  name:"Wave-rippled sand",                 group:"Marine (Walker)", desc:"Shoreface, fair-weather"},
  {code:"Sb",  name:"Bioturbated sand",                  group:"Marine (Walker)", desc:"Fair-weather conditions, low energy"},
  {code:"Mb",  name:"Bioturbated mud",                   group:"Marine (Walker)", desc:"Offshore, lagoon"},
  {code:"Lt",  name:"Lenticular bedding",                group:"Marine (Walker)", desc:"Tidal-flat, mixed flat"},
  {code:"Wb",  name:"Wavy bedding",                      group:"Marine (Walker)", desc:"Tidal-flat, mixed-energy"},
  {code:"Fb",  name:"Flaser bedding",                    group:"Marine (Walker)", desc:"Tidal-flat sand-dominated"},
  // === Bouma turbidite ===
  {code:"Ta",  name:"Massive / graded sand",             group:"Turbidite (Bouma)", desc:"Rapid deposition from high-density turbulent flow"},
  {code:"Tb",  name:"Plane-laminated sand",              group:"Turbidite (Bouma)", desc:"Upper flow regime"},
  {code:"Tc",  name:"Ripple cross-laminated sand",       group:"Turbidite (Bouma)", desc:"Climbing ripples, waning flow"},
  {code:"Td",  name:"Plane-laminated silt / fine sand",  group:"Turbidite (Bouma)", desc:"Low-density tail of flow"},
  {code:"Te",  name:"Pelagic / hemipelagic mud",         group:"Turbidite (Bouma)", desc:"Background suspension settling"},
  // === Carbonate ===
  {code:"M",   name:"Mudstone",                          group:"Carbonate (Dunham)", desc:"<10% grains, mud-supported"},
  {code:"W",   name:"Wackestone",                        group:"Carbonate (Dunham)", desc:">10% grains, mud-supported"},
  {code:"Pk",  name:"Packstone",                         group:"Carbonate (Dunham)", desc:"Grain-supported with mud matrix"},
  {code:"G",   name:"Grainstone",                        group:"Carbonate (Dunham)", desc:"Grain-supported, no mud"},
  {code:"B",   name:"Boundstone",                        group:"Carbonate (Dunham)", desc:"In-place organic binding (reef framework)"},
  {code:"Fl-c",name:"Floatstone",                        group:"Carbonate (Embry-Klovan)", desc:"Matrix-supported, >2 mm grains"},
  {code:"R",   name:"Rudstone",                          group:"Carbonate (Embry-Klovan)", desc:"Grain-supported, >2 mm grains"},
]);

/* XRD MINERAL PALETTE — keyed by canonical mineral names */
const XRD_COLOR = Object.freeze({
  /* tectosilicates — warm */
  "Quartz":      "#E8D5A0",
  "Plagioclase": "#E0A5B0",
  "K-feldspar":  "#D88AA0",
  "Feldspar":    "#DC97A8",   /* legacy generic */
  /* carbonates — cool blue */
  "Calcite":     "#B8D1DE",
  "Dolomite":    "#C5A5B9",
  "Siderite":    "#B86B5A",
  "Ankerite":    "#C89A98",
  /* clays — greens */
  "Illite":      "#7A8870",
  "Smectite":    "#9BAA82",
  "Kaolinite":   "#B6C29A",
  "Chlorite":    "#5E7A5B",
  "Mica":        "#8A9A7A",
  "Muscovite":   "#A0B090",
  "Biotite":     "#4D5C44",
  "Clay":        "#7A8870",   /* legacy generic */
  /* sulphides / sulphates */
  "Pyrite":      "#4A4438",
  "Anhydrite":   "#E6DFC4",
  "Gypsum":      "#F0EAD0",
  "Halite":      "#EDE7D4",
  "Barite":      "#C0B39A",
  /* minor */
  "Glauconite":  "#6D7E3E",
  "Apatite":     "#BBA3D4",
  "Zircon":      "#8A7FA0",
  "Organic":     "#2F2A25",
  "Other":       "#C4B8A6",
});
const XRD_FALLBACK = Object.freeze(["#B8C09A","#D4B6BA","#C5CBB5","#CCCCCC","#A89F8A","#B4A89A","#9EA8B3"]);

/* XRD MINERAL PATTERN MOTIFS — lithology-inspired
   ============================================================
   Each named mineral maps to a motif that hints at the rock type
   the mineral typically signifies:
     • tectosilicates (Quartz, Feldspar) → fine dots, sandstone-like
     • carbonates (Calcite, Dolomite)    → bricks / rhombi
     • clays (Illite, Smectite, etc.)    → horizontal stripes (shale)
     • sulphides (Pyrite)                → dense X cross-hatch
     • evaporites (Anhydrite, Gypsum,
       Halite, Barite)                   → diagonal hatching variants
     • minor (Glauconite, Apatite, etc.) → stipple / dots
   Unknown mineral names rotate through XRD_FALLBACK_MOTIFS so the
   stack stays visually distinguishable even on noncanonical sheets. */
const XRD_MOTIF = Object.freeze({
  "Quartz":"dots", "Plagioclase":"dots", "K-feldspar":"dots", "Feldspar":"dots",
  "Calcite":"bricks", "Dolomite":"rhombi", "Siderite":"bricks", "Ankerite":"rhombi",
  "Illite":"stripes", "Smectite":"stripes", "Kaolinite":"stripes", "Chlorite":"stripes",
  "Mica":"stripes", "Muscovite":"stripes", "Biotite":"stripes", "Clay":"stripes",
  "Pyrite":"xhatch",
  "Anhydrite":"hatch", "Gypsum":"crosshatch", "Halite":"plus", "Barite":"hatch",
  "Glauconite":"stipple", "Apatite":"dots", "Zircon":"stipple",
  "Organic":"solid", "Other":"solid",
});
const XRD_FALLBACK_MOTIFS = Object.freeze(["dots","stripes","hatch","rhombi","xhatch","stipple","crosshatch"]);

/* Inner SVG (motif overlay) for a given motif painted over a tinted
   base. The dark accent is auto-derived from the base via adjustLuminance,
   so every mineral keeps its identity colour while gaining texture.

   `scale` is the patternTransform scale that will be applied to the whole
   tile by xrdAllPatternsSvg (so the XRD motif spacing matches the FGDC /
   GOST lithology patterns — see XRD_TARGET_PITCH_PX). Stroke widths and dot radii
   are divided by that scale so the *rendered* line weight stays crisp
   (~0.3-0.45 px, matching FGDC's 0.3 px hairlines) instead of fattening
   up 8× and smudging at print resolution. Only the geometry (the spacing
   between dots / lines) scales up; the marks themselves stay fine. */
function xrdMotifInner(motif, base, scale){
  const dk = adjustLuminance(base, -0.42);
  scale = scale || 1;
  // Target rendered line weight ≈ 0.36 px (FGDC uses 0.3 px in a viewBox
  // scaled to 64 px). Dots: a small but visible disc once scaled.
  const sw = (0.36 / scale).toFixed(3);   // stroke width in tile units
  const r  = (0.32 / scale).toFixed(3);   // dot radius in tile units
  switch(motif){
    case "dots":
      // 9 dots per 8-unit tile in a 3×3 grid offset — much finer.
      return `<circle cx="1" cy="1" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="4" cy="1" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="7" cy="1" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="2.5" cy="3" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="5.5" cy="3" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="1" cy="5" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="4" cy="5" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="7" cy="5" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="2.5" cy="7" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="5.5" cy="7" r="${r}" fill="${dk}" opacity=".75"/>`;
    case "bricks":
      // Four brick courses per 6-unit tile with offset staggering.
      return `<path d="M0 1.5 H12 M0 3 H12 M0 4.5 H12 M0 0 V6 M3 0 V1.5 M6 1.5 V3 M9 3 V4.5 M6 4.5 V6 M12 0 V6" stroke="${dk}" stroke-width="${sw}" fill="none" opacity=".75"/>`;
    case "rhombi":
      // Three nested rhombi per 12×8 tile — finest net.
      return `<path d="M0 4 L6 0 L12 4 L6 8 Z M2 4 L6 1.3 L10 4 L6 6.7 Z M4 4 L6 2.7 L8 4 L6 5.3 Z" fill="none" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`;
    case "stripes":
      // Six horizontal lines per 8-unit tile — much finer.
      return `<line x1="0" y1=".5" x2="8" y2=".5" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`
           + `<line x1="0" y1="2" x2="8" y2="2" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`
           + `<line x1="0" y1="3.5" x2="8" y2="3.5" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`
           + `<line x1="0" y1="5" x2="8" y2="5" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`
           + `<line x1="0" y1="6.5" x2="8" y2="6.5" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`
           + `<line x1="0" y1="8" x2="8" y2="8" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`;
    case "xhatch":
      // Cross-pattern with three diagonals each way at finer spacing.
      return `<path d="M0 2.7 L2.7 0 M0 5.3 L5.3 0 M0 8 L8 0 M2.7 8 L8 2.7 M5.3 8 L8 5.3 M0 5.3 L2.7 8 M0 2.7 L5.3 8 M0 0 L8 8 M2.7 0 L8 5.3 M5.3 0 L8 2.7" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`;
    case "hatch":
      // Four parallel diagonals — finer slope hatching.
      return `<path d="M0 8 L8 0 M0 6 L6 0 M0 4 L4 0 M0 2 L2 0 M2 8 L8 2 M4 8 L8 4 M6 8 L8 6" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`;
    case "crosshatch":
      // Three crosshatches each direction — fine net.
      return `<path d="M0 0 L8 8 M0 8 L8 0 M0 2.7 L5.3 8 M2.7 0 L8 5.3 M0 5.3 L2.7 8 M5.3 0 L8 2.7" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`;
    case "plus":
      // 9 plus signs per 8-unit tile in 3×3 grid — finer.
      return `<path d="M.5 1.5 H1.5 M1 1 V2 M3.5 1.5 H4.5 M4 1 V2 M6.5 1.5 H7.5 M7 1 V2 M.5 4 H1.5 M1 3.5 V4.5 M3.5 4 H4.5 M4 3.5 V4.5 M6.5 4 H7.5 M7 3.5 V4.5 M.5 6.5 H1.5 M1 6 V7 M3.5 6.5 H4.5 M4 6 V7 M6.5 6.5 H7.5 M7 6 V7" stroke="${dk}" stroke-width="${sw}" opacity=".75"/>`;
    case "stipple":
      // Dense pseudo-random stipple — 16 small dots per tile.
      return `<circle cx=".7" cy=".8" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="2.3" cy="1.4" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="4.1" cy=".6" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="5.8" cy="1.7" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="7.2" cy=".9" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="1.2" cy="2.9" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="3.4" cy="3.3" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="5.1" cy="2.8" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="6.9" cy="3.5" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx=".8" cy="4.7" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="2.6" cy="5.2" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="4.3" cy="4.9" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="6.2" cy="5.4" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="1.5" cy="6.8" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="3.7" cy="7.1" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="5.6" cy="6.6" r="${r}" fill="${dk}" opacity=".75"/>`
           + `<circle cx="7.4" cy="7.3" r="${r}" fill="${dk}" opacity=".75"/>`;
    case "solid":
    default:
      return "";
  }
}
function xrdMotifTile(motif){
  // Native tile dimensions matching the coordinate values used by
  // xrdMotifInner (dots/stripes/etc are drawn against an 8-unit grid;
  // bricks against a 12×6 grid; rhombi against 12×8). The rendered
  // pattern is then scaled via patternTransform in xrdAllPatternsSvg
  // so motif feature spacing matches the FGDC/GOST lithology patterns
  // without having to rewrite every coordinate.
  if (motif === "bricks") return [12, 6];
  if (motif === "rhombi") return [12, 8];
  return [8, 8];
}
/* Native feature pitch (in tile units) of each motif — the centre-to-
   centre spacing of its repeating element (dot-to-dot, line-to-line,
   brick course height, rhombus net). Used to pick a per-motif
   patternTransform scale so every motif renders at a common ~3.7 px
   pitch, matching the FGDC sandstone stipple (~3.5 px) and carbonate
   line spacing (~4.5 px). Without this, motifs with different native
   pitches (dots ~3 u, stripes/bricks ~1.5 u) would render at different
   visual densities. */
function xrdMotifPitch(motif){
  switch(motif){
    case "dots":       return 3;    // horizontal dot spacing in the 8-unit grid
    case "stipple":    return 1.8;  // dense scatter
    case "stripes":    return 1.5;  // line-to-line
    case "bricks":     return 1.5;  // course height
    case "rhombi":     return 2;    // net spacing
    case "hatch":      return 2;    // diagonal spacing
    case "xhatch":     return 2.7;  // diagonal spacing
    case "crosshatch": return 2.7;
    case "plus":       return 3;    // plus-to-plus
    default:           return 3;
  }
}
function xrdSafeIdSuffix(name){
  return String(name).replace(/[^A-Za-z0-9]/g, "_");
}
/* Pattern-id resolver used by every XRD render path AND the legend.
   Known mineral → its named pattern; unknown → fallback by column index. */
function xrdPatternUrl(name, idx){
  if (Object.prototype.hasOwnProperty.call(XRD_MOTIF, name)){
    return `url(#xrd-pat-${xrdSafeIdSuffix(name)})`;
  }
  return `url(#xrd-pat-fb-${(idx|0) % XRD_FALLBACK.length})`;
}
/* Emit all XRD <pattern> elements as a single SVG string. Called once
   from defsSvg() so every pattern is globally available — track body,
   legend swatch, exports — without per-render duplication.

   Scale calibration. The FGDC / GOST lithology patterns tile at 64 px, but
   each 64 px tile is DENSE — e.g. FGDC sandstone "601" packs ~256 stipple
   dots into its tile, giving a real dot-to-dot pitch of only ~3.5 px, and
   the carbonate line patterns sit ~4.5 px apart. So the thing to match is
   the lithology FEATURE pitch (~3.5–4.5 px), not the 64 px tile size.

   Our XRD motifs are authored against small native grids (8 / 12 units)
   whose repeating elements sit ~1.5–3 units apart (see xrdMotifPitch).
   We pick a per-motif patternTransform scale = XRD_TARGET_PITCH_PX /
   nativePitch so EVERY motif — dots, stripes, bricks, rhombi, hatch —
   renders at the same ~3.7 px feature pitch, matching the lithology
   stipple. (A first attempt scaled each whole tile to 64 px, which blew
   the dot pitch out to ~21 px — far coarser than the lithology stipple
   and the source of the "patterns look very big" report.) The scale is
   also passed into xrdMotifInner so stroke weights are divided back down
   to crisp ~0.36 px hairlines (matching FGDC's 0.3 px lines). */
const XRD_TARGET_PITCH_PX = 3.7;
function xrdAllPatternsSvg(){
  let out = "";
  for (const [name, base] of Object.entries(XRD_COLOR)){
    const motif = XRD_MOTIF[name] || "solid";
    const [tw, th] = xrdMotifTile(motif);
    const scale = (XRD_TARGET_PITCH_PX / xrdMotifPitch(motif));
    const sf = scale.toFixed(4);
    out += `<pattern id="xrd-pat-${xrdSafeIdSuffix(name)}" width="${tw}" height="${th}" patternUnits="userSpaceOnUse" patternTransform="scale(${sf})">`
         + `<rect width="${tw}" height="${th}" fill="${base}"/>`
         + xrdMotifInner(motif, base, scale)
         + `</pattern>`;
  }
  XRD_FALLBACK.forEach((base, i) => {
    const motif = XRD_FALLBACK_MOTIFS[i % XRD_FALLBACK_MOTIFS.length];
    const [tw, th] = xrdMotifTile(motif);
    const scale = (XRD_TARGET_PITCH_PX / xrdMotifPitch(motif));
    const sf = scale.toFixed(4);
    out += `<pattern id="xrd-pat-fb-${i}" width="${tw}" height="${th}" patternUnits="userSpaceOnUse" patternTransform="scale(${sf})">`
         + `<rect width="${tw}" height="${th}" fill="${base}"/>`
         + xrdMotifInner(motif, base, scale)
         + `</pattern>`;
  });
  return out;
}

/* ---------------------------------------------------------------------
   FGDC pattern + fossil-symbol emitters.
   Build <pattern> defs for the FGDC 600-/700-series lithology patterns
   (used by drawLithGS when state.symbolStyle === "fgdc") and <symbol>
   defs for the FGDC fossil pictograms (used by drawBio, drawPlants,
   drawRoots, drawIchno when in FGDC mode).
   The patterns/symbols themselves come from FGDC_PATTERN_DATA and
   FGDC_FOSSIL_DATA — frozen objects defined in the embedded data
   module above (auto-generated from the FGDC-STD-013-2006 SVG assets).
   --------------------------------------------------------------------- */
function fgdcPatternsSvg(){
  // Inline-content rendering: emit each FGDC pattern's SVG content
  // *directly inside* the <pattern> element, not via <image href>. This
  // matters because <image>-based pattern tiles get rasterized by the
  // browser at the pattern's native pixel size, and adjacent tiles
  // round to slightly different sub-pixel boundaries, producing visible
  // dark seams between tiles. Inline SVG strokes are rendered natively
  // in the pattern's coordinate space, so tiles connect seamlessly.
  //
  // Each pattern entry stores:
  //   vb: viewBox string (preserves FGDC's negative-y coordinates)
  //   s:  inner SVG markup (no <svg> wrapper, no clipping rect)
  //
  // The pattern's width/height come from the viewBox dimensions; we
  // scale uniformly so the tile reads larger on both screen and print.
  // Previously TILE_PX = 32 produced patterns that were fine on screen
  // but too fine to see at print resolution (300 DPI, 72 SVG units/in)
  // — the sparse sandstone stipple in particular would lose its dots
  // when downsampled to A4. Doubling to 64 makes each pattern tile
  // ~9 mm at print scale instead of ~4.5 mm, which keeps individual
  // hatch lines and stipple dots visible after PDF rasterisation.
  // This does NOT change track widths — the LITH bed body still fills
  // the same column rect; the pattern just tiles less frequently
  // within that rect, so each motif is visually larger.
  const TILE_PX = 64;
  let out = "";
  for (const code in FGDC_PATTERN_DATA){
    const p = FGDC_PATTERN_DATA[code];
    // Parse viewBox to get native width/height
    const vb = p.vb.split(/\s+/).map(Number);
    const vw = vb[2], vh = vb[3];
    const scale = (TILE_PX / Math.max(vw, vh)).toFixed(4);
    // patternContentUnits="userSpaceOnUse" + viewBox on the <pattern>
    // makes the inner content use the FGDC's own coordinate system
    // directly, including its negative-y origin.
    out += `<pattern id="fgdc-${code}" patternUnits="userSpaceOnUse" `
         + `width="${vw}" height="${vh}" viewBox="${p.vb}" `
         + `patternTransform="scale(${scale})">`
         + p.s
         + `</pattern>`;
  }
  return out;
}
function fgdcFossilSymsSvg(){
  // Emit a <symbol> for every entry in FGDC_FOSSIL_DATA so the
  // biostratigraphy / plants / roots / ichno drawers can <use> them
  // directly: <use href="#fgdc-foss-foram" .../>. Each symbol carries
  // its native viewBox so the user-site sizing (width/height on <use>)
  // produces a correctly proportioned icon. The inline SVG content
  // (FGDC §10.2 fossil symbols) draws in solid black on transparent so
  // they overlay any background tint cleanly.
  let out = "";
  for (const name in FGDC_FOSSIL_DATA){
    const f = FGDC_FOSSIL_DATA[name];
    out += `<symbol id="fgdc-foss-${name}" viewBox="${f.vb}" `
         + `preserveAspectRatio="xMidYMid meet">`
         + f.s
         + `</symbol>`;
  }
  return out;
}

/* gostPatternsSvg() — same shape as fgdcPatternsSvg(), but iterates
   GOST_PATTERN_DATA. Each pattern becomes a <pattern id="gost-<code>">
   in the shared <defs>. Tiles use the same physical density (TILE_PX) so
   GOST and FGDC patterns are visually comparable when switching standards. */
/* gostTileBox(p) — return the true repeating tile cell {x,y,w,h} in the
   pattern's own viewBox coordinate space.

   The CGM→SVG conversion inflated the declared viewBox of some tiles by a
   few units beyond the actual GOST cell (the framing <rect> drawn with
   stroke-width="1.0"). When the <pattern> tiled on that inflated viewBox,
   the surplus units showed up as a thin gap and a doubled line along the
   right / bottom edge where neighbouring tiles met (e.g. Limestone 1700,
   1322, the tuff series, etc.).

   The cell that actually tiles is the framing rect, not the viewBox, so we
   read the rect back out of the markup, map it through the tile's
   `translate(tx ty) scale(1 -1)` group transform into viewBox space, and use
   that as the pattern viewBox + width/height. Tiles then butt together with
   no sliver and a single shared edge line. Tiles without a framing rect
   (only 1486) fall back to the declared viewBox. */
function gostTileBox(p){
  const vb = p.vb.split(/\s+/).map(Number);
  const fallback = {x:vb[0], y:vb[1], w:vb[2], h:vb[3]};
  // group transform: translate(tx ty) scale(1 -1)
  const gm = p.s.match(/translate\(\s*(-?[\d.]+)\s+(-?[\d.]+)\s*\)\s*scale\(\s*1\s+-1\s*\)/);
  // framing rect = the only rect drawn at hairline width (stroke-width="1.0")
  const rm = p.s.match(/<rect\s+x="(-?[\d.]+)"\s+y="(-?[\d.]+)"\s+width="([\d.]+)"\s+height="([\d.]+)"[^>]*stroke-width="1(?:\.0)?"/);
  if (!gm || !rm) return fallback;
  const tx = +gm[1], ty = +gm[2];
  const rx = +rm[1], ry = +rm[2], rw = +rm[3], rh = +rm[4];
  // map rect corners through translate + y-flip into viewBox space
  const x0 = tx + rx;                 // left edge
  const yTop = ty - (ry + rh);        // top edge (y is flipped)
  return {x:x0, y:yTop, w:rw, h:rh};
}

function gostPatternsSvg(){
  const TILE_PX = 64;
  let out = "";
  for (const code in GOST_PATTERN_DATA){
    const p = GOST_PATTERN_DATA[code];
    const box = gostTileBox(p);
    const scale = (TILE_PX / Math.max(box.w, box.h)).toFixed(4);
    out += `<pattern id="gost-${code}" patternUnits="userSpaceOnUse" `
         + `width="${box.w}" height="${box.h}" `
         + `viewBox="${box.x} ${box.y} ${box.w} ${box.h}" `
         + `patternTransform="scale(${scale})">`
         + p.s
         + `</pattern>`;
  }
  return out;
}


