/* BIOTURBATION INDEX (Droser & Bottjer 1986) 0–6 scale.
   Each grade maps to a distinctive shade — pale = undisturbed, dark = chaotic. */
const BIOT_INDEX = Object.freeze([
  {grade:0, color:"#F5EFE2", name:"0 — no bioturbation"},
  {grade:1, color:"#E4DDC8", name:"1 — sparse (1–5%)"},
  {grade:2, color:"#D5C8A4", name:"2 — uncommon (6–30%)"},
  {grade:3, color:"#B9A47A", name:"3 — moderate (31–60%)"},
  {grade:4, color:"#9A8355", name:"4 — common (61–90%)"},
  {grade:5, color:"#6F5A38", name:"5 — abundant (91–99%)"},
  {grade:6, color:"#40321E", name:"6 — complete (100%, fabric destroyed)"},
]);
function biotColor(g){
  g = Math.max(0, Math.min(6, Math.round(+g)));
  return BIOT_INDEX[g].color;
}

