/* Linkages so typing one group surfaces zones from synonyms / parents.
   Mirrors MARKER_SPECIES_GROUP_LINKS. */
const ZONE_SCHEME_GROUP_LINKS = Object.freeze({
  "Coccoliths":               ["Calcareous nannofossils"],
  "Calcareous nannofossils":  ["Coccoliths"],
  "Foraminifera":             ["Planktonic foraminifera","Benthic foraminifera"],
  "Planktonic foraminifera":  ["Foraminifera"],
  "Benthic foraminifera":     ["Foraminifera"],
  "Spores":                   ["Spores & pollen","Palynomorphs"],
  "Pollen":                   ["Spores & pollen","Palynomorphs"],
  "Spores & pollen":          ["Spores","Pollen","Palynomorphs"],
  "Palynomorphs":             ["Spores","Pollen","Spores & pollen","Dinoflagellates"],
  "Cephalopods":              ["Ammonites","Belemnites"],
});

function zoneOpts(row){
  // Canonicalize fossil group via the same biofossilCanon used for
  // Marker_Species, then collect zones from the canonical group plus
  // any closely-linked groups (Coccoliths ↔ Calcareous nannofossils, etc.).
  let raw = row && row.Fossil_Group ? String(row.Fossil_Group).trim() : "";
  let canon = "";
  if (raw){
    try { canon = (typeof biofossilCanon === "function") ? biofossilCanon(raw) : raw; }
    catch(_){ canon = raw; }
  }
  const seen = new Set();
  const out  = [];
  const groupList = [];
  const pushGroup = g => {
    if (!g || groupList.includes(g)) return;
    if (ZONE_SCHEMES_BY_GROUP[g] && ZONE_SCHEMES_BY_GROUP[g].length) groupList.push(g);
  };
  if (canon){
    pushGroup(canon);
    (ZONE_SCHEME_GROUP_LINKS[canon] || []).forEach(pushGroup);
  }
  // No group → pull a small representative sample from across schemes
  if (!groupList.length && !canon){
    Object.entries(ZONE_SCHEMES_BY_GROUP).forEach(([g, arr]) => {
      arr.slice(0, 3).forEach(s => {
        if (seen.has(s)) return;
        seen.add(s); out.push({value:s, label:s});
      });
    });
  }
  groupList.forEach(g => {
    (ZONE_SCHEMES_BY_GROUP[g] || []).forEach(s => {
      if (seen.has(s)) return;
      seen.add(s); out.push({value:s, label:s});
    });
  });
  // Append project-specific zones (already in workbook + working rows)
  // — same group-aware filter as markerSpeciesOpts. A custom zone like
  // "Zone X-3 (project)" typed on a Dinoflagellate row shouldn't be
  // suggested when picking zones on a Foraminifera row.
  const append = v => {
    if (v == null || v === "") return;
    const s = String(v).trim();
    if (!s || seen.has(s)) return;
    seen.add(s); out.push({value:s, label:s});
  };
  const acceptGroups = new Set();
  if (canon){
    acceptGroups.add(canon);
    (ZONE_SCHEME_GROUP_LINKS[canon] || []).forEach(g => acceptGroups.add(g));
  }
  // Also accept exact (case-insensitive) match against the current
  // row's raw group spelling, so custom group names still cluster
  // their own zones together.
  const rawLower = raw ? raw.toLowerCase() : "";
  const rowGroupMatches = (rowGroupRaw) => {
    if (rowGroupRaw == null || rowGroupRaw === "") return false;
    if (!acceptGroups.size && !rawLower) return false;
    const parts = String(rowGroupRaw).split(/\s*[;,|\/]\s*/).filter(Boolean);
    for (const p of parts){
      const trimmed = p.trim();
      if (rawLower && trimmed.toLowerCase() === rawLower) return true;
      let c;
      try { c = (typeof biofossilCanon === "function") ? biofossilCanon(trimmed) : trimmed; }
      catch(_){ c = trimmed; }
      if (acceptGroups.has(c)) return true;
    }
    return false;
  };
  if ((acceptGroups.size || rawLower) && Array.isArray(state.biostrat)){
    state.biostrat.forEach(r => {
      if (!r) return;
      if (rowGroupMatches(r.group)) append(r.zone);
    });
  }
  if ((acceptGroups.size || rawLower) && Estate && Estate.currentSheet
      && Estate.currentSheet.stateKey === "biostrat"
      && Array.isArray(Estate.rows)){
    Estate.rows.forEach(r => {
      if (!r) return;
      if (rowGroupMatches(r["Fossil_Group"])) append(r["Zone"]);
    });
  }
  return out;
}

/* Marker-species → fossil-group resolution rules.
   Some FOSSIL_GROUP entries are near-synonyms or genuine subsets that
   should share marker species. We keep curated species lists per
   canonical group, but when the user picks one of these aliases the
   resolver redirects to a richer list:
     • "Coccoliths" → "Calcareous nannofossils" (essentially synonyms)
     • "Echinoids", "Crinoids" → fold into the broader "Echinoderms"
       list AND keep their own narrower lists, then merge so the user
       sees both
     • "Cephalopods" overlaps with Ammonites + Belemnites — show a union
   Bidirectional links are preferred where they don't introduce noise. */
const MARKER_SPECIES_GROUP_LINKS = Object.freeze({
  "Coccoliths":               ["Calcareous nannofossils"],
  "Calcareous nannofossils":  ["Coccoliths"],
  "Echinoids":                ["Echinoderms"],
  "Echinoderms":              ["Echinoids","Crinoids"],
  "Crinoids":                 ["Echinoderms"],
  "Cephalopods":              ["Ammonites","Belemnites"],
  "Spores":                   ["Spores & pollen","Palynomorphs"],
  "Pollen":                   ["Spores & pollen","Palynomorphs"],
  "Spores & pollen":          ["Spores","Pollen","Palynomorphs"],
  "Palynomorphs":             ["Spores","Pollen","Spores & pollen"],
  "Foraminifera":             ["Planktonic foraminifera","Benthic foraminifera"],
  "Planktonic foraminifera":  ["Foraminifera"],
  "Benthic foraminifera":     ["Foraminifera"],
});

function markerSpeciesOpts(row){
  // Canonicalize the group through biofossilCanon, which is the same
  // alias resolver the rest of the viewer uses. Typing "nannofossils",
  // "coccoliths", "Coccolithophore", or "Calcareous nannofossils"
  // therefore all converge on the same suggestion list.
  let raw = row && row.Fossil_Group ? String(row.Fossil_Group).trim() : "";
  let canon = "";
  if (raw){
    try { canon = (typeof biofossilCanon === "function") ? biofossilCanon(raw) : raw; }
    catch(_){ canon = raw; }
  }
  const seen = new Set();
  const out  = [];
  // Build the candidate group list: the canonical group + any closely
  // linked groups (synonyms, parent/child taxa).
  const groupList = [];
  const pushGroup = g => {
    if (!g || groupList.includes(g)) return;
    if (MARKER_SPECIES_BY_GROUP[g]) groupList.push(g);
  };
  if (canon){
    pushGroup(canon);
    (MARKER_SPECIES_GROUP_LINKS[canon] || []).forEach(pushGroup);
  }
  // No group → small union sample so the dropdown isn't empty
  if (!groupList.length && !canon){
    Object.values(MARKER_SPECIES_BY_GROUP).forEach(arr => {
      arr.slice(0, 4).forEach(s => {
        if (seen.has(s)) return;
        seen.add(s); out.push({value:s, label:s});
      });
    });
  }
  // Add curated species from each candidate group, in order, dedup'd.
  groupList.forEach(g => {
    (MARKER_SPECIES_BY_GROUP[g] || []).forEach(s => {
      if (seen.has(s)) return;
      seen.add(s); out.push({value:s, label:s});
    });
  });
  // Append values already in the workbook (in-state + working rows)
  // so the user sees their own additions even if they're not in the
  // curated list — BUT only species typed on rows belonging to the
  // SAME group (canonically) or a linked group. Without this filter,
  // a species typed on a Dinoflagellate row would leak into the
  // Foraminifera/Conodont/Ammonite/etc dropdowns, which is taxonomically
  // nonsensical and clutters every popup. When the current row has no
  // group set, we skip user-typed appends entirely — with no group
  // context we can't filter sensibly, and the curated-union starter
  // list is already there.
  const append = (v) => {
    if (v == null || v === "") return;
    const s = String(v).trim();
    if (!s || seen.has(s)) return;
    seen.add(s); out.push({value:s, label:s});
  };
  /* Build a set of groups (canonical) whose user-typed species we'll
     accept. Always includes the current canonical group and its links;
     stays empty when canon is empty so we don't pollute the starter list. */
  const acceptGroups = new Set();
  if (canon){
    acceptGroups.add(canon);
    (MARKER_SPECIES_GROUP_LINKS[canon] || []).forEach(g => acceptGroups.add(g));
  }
  // Also keep the raw user spelling so custom groups (not in the
  // curated FOSSIL_GROUP map) still cluster their own species.
  const rawLower = raw ? raw.toLowerCase() : "";
  const rowGroupMatches = (rowGroupRaw) => {
    if (rowGroupRaw == null || rowGroupRaw === "") return false;
    if (!acceptGroups.size && !rawLower) return false;
    // Multiple groups can be listed (separated by ;,|/). Match if ANY
    // of them canonicalises into the accept set, or matches the raw
    // spelling of the current row's group (case-insensitive).
    const parts = String(rowGroupRaw).split(/\s*[;,|\/]\s*/).filter(Boolean);
    for (const p of parts){
      const trimmed = p.trim();
      if (rawLower && trimmed.toLowerCase() === rawLower) return true;
      let c;
      try { c = (typeof biofossilCanon === "function") ? biofossilCanon(trimmed) : trimmed; }
      catch(_){ c = trimmed; }
      if (acceptGroups.has(c)) return true;
    }
    return false;
  };
  if ((acceptGroups.size || rawLower) && Array.isArray(state.biostrat)){
    state.biostrat.forEach(r => {
      if (!r) return;
      if (rowGroupMatches(r.group)) append(r.species);
    });
  }
  if ((acceptGroups.size || rawLower) && Estate && Estate.currentSheet
      && Estate.currentSheet.stateKey === "biostrat"
      && Array.isArray(Estate.rows)){
    Estate.rows.forEach(r => {
      if (!r) return;
      if (rowGroupMatches(r["Fossil_Group"])) append(r["Marker_Species"]);
    });
  }
  return out;
}

/* ---------- Live (data-driven) suggestion factories ----------
   For project-specific fields like Formation/Member/Sample_ID where no
   universal vocabulary exists, we offer suggestions derived from the
   data itself: every unique value seen in state.<stateKey>[].<field>
   becomes a suggestion. The user sees what they (or an upstream geologist)
   already typed and can stay consistent. Includes the editor's working
   rows for the current sheet so values typed during the session also
   appear after a moment. */
function liveOptsFor(stateKey, stateField, currentSheetExcelKey){
  return function(row){
    const seen = new Set();
    const out = [];
    // From committed state
    const arr = state[stateKey];
    if (Array.isArray(arr)){
      arr.forEach(r => {
        const v = r && r[stateField];
        if (v == null || v === "") return;
        const s = String(v).trim();
        if (!s || seen.has(s)) return;
        seen.add(s); out.push({value:s, label:s});
      });
    }
    // From the editor's current working rows (if user has typed values
    // not yet applied AND we're editing the same sheet)
    if (Estate && Estate.currentSheet && Estate.currentSheet.stateKey === stateKey
        && Array.isArray(Estate.rows) && currentSheetExcelKey){
      Estate.rows.forEach(r => {
        const v = r && r[currentSheetExcelKey];
        if (v == null || v === "") return;
        const s = String(v).trim();
        if (!s || seen.has(s)) return;
        seen.add(s); out.push({value:s, label:s});
      });
    }
    return out;
  };
}

/* Sample_ID suggestions are useful across MANY sheets — RCA, SCAL,
   Archie, NMR T2, MICP, Centrifuge, GS — since the same sample is
   often measured in multiple labs. Pool them into one list. */
function sampleIdOpts(row){
  const seen = new Set();
  const out  = [];
  const sources = [
    ["rca",        "id"],
    ["scal",       "id"],
    ["archie",     "id"],
    ["nmr",        "id"],
    ["micppsd",    "id"],
    ["centrifuge", "id"],
    ["gs",         "id"],
  ];
  sources.forEach(([k, f]) => {
    const arr = state[k];
    if (!Array.isArray(arr)) return;
    arr.forEach(r => {
      const v = r && r[f];
      if (v == null || v === "") return;
      const s = String(v).trim();
      if (!s || seen.has(s)) return;
      seen.add(s); out.push({value:s, label:s});
    });
  });
  // Editor's working rows (current sheet only — same Excel header)
  if (Estate && Estate.currentSheet && Array.isArray(Estate.rows)){
    Estate.rows.forEach(r => {
      const v = r && r["Sample_ID"];
      if (v == null || v === "") return;
      const s = String(v).trim();
      if (!s || seen.has(s)) return;
      seen.add(s); out.push({value:s, label:s});
    });
  }
  return out;
}

/* Photo filename suggestions — drawn from state.photoBlobs, which is
   populated when the user clicks "② Load core photos". This makes
   filename entries match disk reality and avoids typos.

   Sorted by leading numeric depth if present (so 1900.0.jpg comes
   before 2050.0.jpg) — useful for box-photo workflows. */
function photoFilenameOpts(){
  const blobs = state.photoBlobs;
  if (!blobs || typeof blobs !== "object") return [];
  // Use a Set to dedupe canonical-vs-display names that point at the
  // same file (the loader stores both a "10.5.jpg" canonical alias
  // and the original "1010.50.jpg" so lookup works either way).
  const seen = new Set();
  const items = [];
  Object.keys(blobs).forEach(name => {
    if (!name || seen.has(name)) return;
    seen.add(name);
    items.push(name);
  });
  // Try to extract a leading depth (digits + optional dot + digits)
  // for sorting; non-numeric names sort to the end alphabetically.
  items.sort((a, b) => {
    const ma = a.match(/^[A-Za-z_-]*?(\d+(?:\.\d+)?)/);
    const mb = b.match(/^[A-Za-z_-]*?(\d+(?:\.\d+)?)/);
    if (ma && mb) return +ma[1] - +mb[1];
    if (ma && !mb) return -1;
    if (!ma && mb) return 1;
    return a.localeCompare(b);
  });
  return items.map(n => ({value:n, label:n}));
}

/* Recognised Well_Info fields. The renderer reads some of these
   specifically (Well_Name, Well_Id, Operator, Core_Top, Core_Base,
   Depth_Unit); anything else round-trips through the workbook but
   doesn't drive visible behaviour. */
const WELL_INFO_FIELDS = [
  {key:"Well_Name",       label:"Well_Name",       hint:"Display name in the header"},
  {key:"Well_Id",         label:"Well_Id",         hint:"Internal/database identifier"},
  {key:"Operator",        label:"Operator",        hint:"Operator / company name"},
  {key:"Field",           label:"Field",           hint:"Field / asset name"},
  {key:"Block",           label:"Block",           hint:"Licence block / lease"},
  {key:"Country",         label:"Country",         hint:"Country"},
  {key:"Region",          label:"Region",          hint:"Basin / region"},
  {key:"Latitude",        label:"Latitude",        hint:"Decimal degrees"},
  {key:"Longitude",       label:"Longitude",       hint:"Decimal degrees"},
  {key:"KB_Elevation",    label:"KB_Elevation",    hint:"Kelly bushing elevation (m)"},
  {key:"GL_Elevation",    label:"GL_Elevation",    hint:"Ground level elevation (m)"},
  {key:"WD",              label:"WD",              hint:"Water depth, offshore (m)"},
  {key:"TVD_Total",       label:"TVD_Total",       hint:"Total true vertical depth (m)"},
  {key:"MD_Total",        label:"MD_Total",        hint:"Total measured depth (m)"},
  {key:"Core_Top",        label:"Core_Top",        hint:"Top of cored interval (m). Used for the depth range."},
  {key:"Core_Base",       label:"Core_Base",       hint:"Base of cored interval (m). Used for the depth range."},
  {key:"Depth_Unit",      label:"Depth_Unit",      hint:"m or ft"},
  {key:"Depth_Reference", label:"Depth_Reference", hint:"e.g. KB, MSL, GL"},
  {key:"Date_Spudded",    label:"Date_Spudded",    hint:"YYYY-MM-DD"},
  {key:"Date_TD",         label:"Date_TD",         hint:"YYYY-MM-DD"},
  {key:"Logger",          label:"Logger",          hint:"Geologist who described the core"},
  {key:"Lab",             label:"Lab",             hint:"Lab that performed analyses"},
  {key:"Comments",        label:"Comments",        hint:"Free notes"},
];
function wellInfoFieldOpts(){
  return WELL_INFO_FIELDS.map(f => ({value:f.key, label:f.label}));
}

/* Cascading suggestions for Well Info "Value" — based on the row's
   Field. Handles a handful of fields with known short vocabularies
   (Depth_Unit, Depth_Reference, Country) and falls back to live values
   from existing wells when the field doesn't have a curated list. */
const WELL_INFO_VALUE_OPTS = Object.freeze({
  Depth_Unit: [
    {value:"m",  label:"m — metres"},
    {value:"ft", label:"ft — feet"},
  ],
  Depth_Reference: [
    {value:"KB",  label:"KB — Kelly bushing"},
    {value:"RT",  label:"RT — rotary table"},
    {value:"DF",  label:"DF — drill floor"},
    {value:"GL",  label:"GL — ground level"},
    {value:"MSL", label:"MSL — mean sea level"},
    {value:"SS",  label:"SS — sub-sea"},
    {value:"MD",  label:"MD — measured depth"},
    {value:"TVD", label:"TVD — true vertical depth"},
  ],
  Country: [
    "Russia","Kazakhstan","Azerbaijan","Turkmenistan","Uzbekistan",
    "United States","Canada","Mexico","Brazil","Argentina","Venezuela",
    "United Kingdom","Norway","Netherlands","Germany","Denmark",
    "Saudi Arabia","UAE","Qatar","Kuwait","Iraq","Iran","Oman",
    "Algeria","Libya","Egypt","Nigeria","Angola","Equatorial Guinea",
    "China","India","Indonesia","Malaysia","Thailand","Vietnam",
    "Australia","Papua New Guinea","New Zealand",
  ].map(c => ({value:c, label:c})),
});
function wellInfoValueOpts(row){
  if (!row || !row.Field) return [];
  const field = String(row.Field).trim();
  if (WELL_INFO_VALUE_OPTS[field]) return WELL_INFO_VALUE_OPTS[field];
  // For other fields, no curated list — return empty so the input is
  // a plain text box (with no datalist). The user can still type freely.
  return [];
}



/* ---------- EDITOR_SHEETS ----------
   Single source of truth for every editable sheet. Each entry binds:
     id        — internal id used for routing
     title     — human-readable title for sidebar / toolbar
     subtitle  — short tag-line shown in the toolbar
     stateKey  — name of the state.* array this sheet edits
     tracks    — comma-list of visual tracks fed by this sheet (help text)
     order     — group label for the sidebar
     columns   — array of {key, label, type, width, getOpts?, hint?, req?}
                 key  is the Excel column header (canonical case);
                 getOpts returns the controlled vocabulary for enum/vocab.
     dynamic   — if true, columns is rebuilt from rows + state-bins
     binsKey   — for multi-bin sheets, the state field holding bin list */
