/* O(1) id → editor-sheet lookup. Several hot paths (applyAll's
   per-draft loop, sidebar nav, sheet switching) called
   EDITOR_SHEETS.find(s => s.id === id) per access. With ~40 sheets
   that's a linear scan every time; on a workbook open + apply
   sequence it shows up in profiles. */
const EDITOR_SHEETS_BY_ID = new Map(EDITOR_SHEETS.map(s => [s.id, s]));
const EDITOR_SHEETS_BY_STATE_KEY = new Map(EDITOR_SHEETS.map(s => [s.stateKey, s]));

/* Build columns for a multi-bin distribution sheet. The bin centres
   are themselves the column headers, in ascending order. */
function buildBinColumns(rows, bins, unit){
  const cols = [
    {key:"Depth",     label:"Depth",     type:T.num,  width:90,  req:true},
    {key:"Sample_ID", label:"Sample_ID", type:T.vocab, width:110, getOpts:sampleIdOpts},
  ];
  const seen = new Set(["Depth","Sample_ID","Notes"]);
  if (Array.isArray(bins)){
    bins.forEach(b => {
      if (!b || !b.key) return;
      if (seen.has(b.key)) return;
      seen.add(b.key);
      // Show the bin CENTRE as a plain number (e.g. "125") in the editable
      // header, matching the numeric format of the data cells below, so a
      // block of values (header + data) copy-pastes cleanly to/from Excel.
      const binLabel = (b.x != null && Number.isFinite(b.x)) ? String(b.x) : b.key;
      cols.push({key:b.key, label:binLabel, ttype:unit, type:T.num, width:75, hint:"bin centre "+binLabel+" "+unit});
    });
  }
  rows.forEach(r => Object.keys(r).forEach(k => {
    if (seen.has(k)) return;
    seen.add(k);
    cols.push({key:k, label:k, ttype:unit, type:T.num, width:75});
  }));
  // Distribution sheets intentionally have NO Notes column — every
  // non-reserved column is a numeric bin, so a pasted block of values
  // maps 1:1 onto bins with nothing in the way.
  return cols;
}

/* ---------- DEHYDRATORS ----------
   state.<key>[] (normalised, terse names) → array of objects keyed by
   Excel column header. This is what the grid edits. */
const SHEET_DEHYDRATE = {
  /* Well_Info is stored as a {Field: Value} object, not an array. We
     convert it to an array of {Field, Value} rows in the canonical
     order (recognised fields first, then any custom fields the user
     added). Empty/unset recognised fields are still shown so the user
     can fill them in. */
  wellInfo: obj => {
    const o = obj || {};
    const out = [];
    const seen = new Set();
    WELL_INFO_FIELDS.forEach(f => {
      seen.add(f.key);
      const v = o[f.key];
      out.push({Field: f.key, Value: v == null ? "" : v});
    });
    // Include any custom fields the user (or upstream) added that
    // aren't in the recognised list.
    Object.keys(o).forEach(k => {
      if (seen.has(k)) return;
      out.push({Field: k, Value: o[k] == null ? "" : o[k]});
    });
    return out;
  },
  /* Stratigraphy dehydrators — identical schema, one per standard table.
     (The shared shape means a single function would do, but keying each
     state array explicitly keeps the dehydrate map a flat 1:1 lookup that
     the editor + exporter both iterate.) */
  stratIcs: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, System:r.system,
    Series:r.series, Stage:r.stage,
    Formation:r.fm, Member:r.mb, Index:r.index, Color:r.color, Notes:r.notes,
  })),
  stratRu: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, System:r.system,
    Series:r.series, Stage:r.stage,
    Formation:r.fm, Member:r.mb, Index:r.index, Color:r.color, Notes:r.notes,
  })),
  stratNa: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, System:r.system,
    Series:r.series, Stage:r.stage,
    Formation:r.fm, Member:r.mb, Index:r.index, Color:r.color, Notes:r.notes,
  })),
  biostrat: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, Zone:r.zone, Fossil_Group:r.group,
    Marker_Species:r.species, Confidence:r.conf, Notes:r.notes,
  })),
  geochron: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, Age_Ma:r.age, Age_Error_Ma:r.err,
    Method:r.method, Material:r.material, Notes:r.notes,
  })),
  cycles: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base,
    Cycle:r.name, Trend:r.trend, Comments:r.comments,
    Boundary:r.boundary, Surface_Type:r.surface,
  })),
  waterLevel: arr => (arr||[])
    .filter(r => r.src === "manual")   // never export auto-built rows
    .map(r => ({
      Top_Depth: r.top, Base_Depth: r.base,
      Sea_Level_m: r.wl, Notes: r.notes,
    })),
  // Same pattern for the MIS Temperature sheet: only persist user-
  // entered manual overrides; auto values re-derive from the curve on
  // load.
  misTemp: arr => (arr||[])
    .filter(r => r.src === "manual")
    .map(r => ({
      Top_Depth: r.top, Base_Depth: r.base,
      Temperature_C: r.temp, Notes: r.notes,
    })),
  systract: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, Tract:r.tract,
    Parasequence_Set:r.ps, Notes:r.notes,
  })),
  coreRuns: arr => (arr||[]).map(r => ({
    Core_Num:r.num, Top_Depth:r.top, Base_Depth:r.base,
    Recovery_pct:r.rec, Notes:r.notes,
  })),
  lithology: arr => (arr||[]).map(r => {
    // Compose "CODE — Name" cells so the editor's vocab dropdown can
    // round-trip the values without losing the inline label. Look up
    // the name from each catalogue independently so the FGDC cell
    // shows the FGDC name and the GOST cell shows the (localised)
    // GOST name. Empty codes produce empty cells.
    // compose(code, cat, isGost) → "CODE — Name" cell. The GOST column
    // uses the verbatim GOST 2.857-75 wording (gostName); the FGDC column
    // uses the t() path.
    const compose = (code, cat, isGost) => {
      if (!code) return "";
      const def = cat[code];
      if (!def) return code;  // custom code — keep verbatim
      const name = isGost
        ? ((typeof gostName === "function") ? gostName(code) : def.name)
        : ((typeof t === "function") ? t(def.name) : def.name);
      return code + " \u2014 " + name;
    };
    return {
      Top_Depth:r.top, Base_Depth:r.base,
      Lithology_FGDC: compose(r.lithFgdc || (state.symbolStyle === "fgdc" ? r.lith : ""), LITH_FGDC, false),
      Lithology_GOST: compose(r.lithGost || (state.symbolStyle === "gost" ? r.lith : ""), LITH_GOST, true),
      Core_Lithology: compose(r.lithCore || (state.symbolStyle === "core" ? r.lith : ""), LITH_CORE, false),
      Grain_Size:r.gs,
      Sorting:r.sorting, Rounding:r.rounding, Colour:r.colour,
      Structures:(r.structures||[]).join(", "),
      Top_Boundary:r.topBoundary||"",
      Short_Desc:r.desc,
    };
  }),
  // Structures sheet round-trip: only export *user-entered* markers,
  // never the ones we derived on-the-fly from the Lithology sheet's
  // own Structures column. Otherwise saving would double-write them.
  thinInterbeds: arr => (arr||[]).map(r => ({Depth:r.d, Type:r.type, Notes:r.notes})),
  impurities: arr => (arr||[]).map(r => ({Depth:r.d, Impurity:r.type, Notes:r.notes})),
  structures: arr => (arr||[]).filter(r => r.src !== "derived").map(r => ({
    Depth:r.d, Structure:r.code, Importance:r.importance||"primary", Dip_Angle:r.dip, Notes:r.note,
  })),
  faunal: arr => (arr||[]).map(r => ({Depth:r.d, Type:r.type, Taxon:r.taxon, Abundance:r.abund, Preservation:r.preservation, Notes:r.notes})),
  biot: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, BI:r.bi, Notes:r.notes,
  })),
  ichno: arr => (arr||[]).map(r => ({
    Depth:r.d, Ichnotaxa:r.taxa, Ichnofacies:r.facies,
    Abundance:r.abund, Notes:r.notes,
  })),
  plants: arr => (arr||[]).map(r => ({
    Depth:r.d, Type:r.type, Abundance:r.abund, Notes:r.notes,
  })),
  roots: arr => (arr||[]).map(r => ({Depth:r.d, Type:r.type||"root", Density:r.density, Notes:r.notes})),
  env: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base,
    Environment:r.name, Facies_Code:r.code, Notes:r.notes,
  })),
  paleocurrent: arr => (arr||[]).map(r => ({
    Depth:r.d, Azimuth:r.azim, Dip:r.dip, Count:r.count,
    Structure:r.structure, Notes:r.notes,
  })),
  hcshows: arr => (arr||[]).map(r => ({
    Depth:r.d, Intensity:r.intensity, Type:r.type,
    Fluorescence:r.fluor, Cut:r.cut, Notes:r.notes,
  })),
  gamma: arr => (arr||[]).map(r => ({Depth:r.d, GR_API:r.gr})),
  spectral: arr => (arr||[]).map(r => ({Depth:r.d, K_pct:r.k, U_ppm:r.u, Th_ppm:r.th})),
  ctdensity: arr => (arr||[]).map(r => ({Depth:r.d, RhoB_gcc:r.rhob})),
  magsus: arr => (arr||[]).map(r => ({
    Depth:r.d, MagSus_SI_e6:r.ms, Declination:r.dec, Inclination:r.inc,
    Polarity:r.pol, Notes:r.notes,
  })),
  rca: arr => (arr||[]).map(r => ({
    Depth:r.d, Sample_ID:r.id, Porosity_pct:r.phi,
    Permeability_mD:r.k, Grain_Density:r.rho, Notes:r.note,
  })),
  saturations: arr => (arr||[]).map(r => ({Depth:r.d, So:r.so, Sg:r.sg, Sw:r.sw})),
  archie: arr => (arr||[]).map(r => ({
    Depth:r.d, Sample_ID:r.id, m_exponent:r.m, n_exponent:r.n,
    Swi_pct:r.swi, Notes:r.notes,
  })),
  scal: arr => (arr||[]).map(r => ({
    Depth:r.d, Sample_ID:r.id, Swi_pct:r.swi, Sor_pct:r.sor,
    kro_at_Swi:r.kro, Sw_crossover:r.cross, System:r.system, Notes:r.notes,
  })),
  fractures: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, Density_per_m:r.dens,
    Mean_Azimuth:r.azim, Mean_Dip:r.dip, Set_Name:r.setName, Notes:r.notes,
  })),
  // Source rock: export the LIVE computed Rock-Eval parameters (HI/OI/PI)
  // and the resolved kerogen type via srResolve(), so the saved workbook
  // matches exactly what the TOC/Pyrolysis/HC-potential tracks plot rather
  // than any stale stored indices. Raw measurements are written verbatim.
  sourcerock: arr => (arr||[]).map(srResolve).map(r => ({
    Depth:r.d, TOC_pct:r.toc, Ro_pct:r.ro, Tmax_C:r.tmax,
    S1_mgHCgRock:r.s1, S2_mgHCgRock:r.s2, S3_mgCO2gRock:r.s3,
    HI: r.hi!=null ? Math.round(r.hi) : null,
    OI: r.oi!=null ? Math.round(r.oi) : null,
    PI: r.pi!=null ? +(+r.pi).toFixed(3) : null,
    Kerogen_Type:r.kerogen, Notes:r.notes,
  })),
  xrd: arr => (arr||[]).map(r => {
    const o = {Depth:r.d};
    if (r.vals) Object.assign(o, r.vals);
    return o;
  }),
  nmr:        arr => binDehydrate(arr, state.nmrBins),
  micppsd:    arr => binDehydrate(arr, state.micppsdBins),
  centrifuge: arr => binDehydrate(arr, state.centrifugeBins),
  gs:         arr => binDehydrate(arr, state.gsBins),
  gsstats: arr => {
    // Always export the RESOLVED grain-size statistics — i.e. exactly what
    // the GS percentiles / GS moments tracks plot. gsStatsResolved() already
    // honours manual GrainSizeStats overrides where present and otherwise
    // computes the geometric Folk & Ward measures from the GrainSize
    // distribution, so the saved workbook reflects the current tracks. We
    // recover Sample_ID / Notes from any matching manual override row.
    const sheet = Array.isArray(arr) ? arr : (state.gsstats || []);
    const meta = new Map();
    sheet.forEach(r => { if (Number.isFinite(r.d)) meta.set(+r.d.toFixed(4), r); });
    return gsStatsResolved().map(r => {
      const m = meta.get(+(+r.d).toFixed(4));
      return {
        Depth:r.d, Sample_ID:(m && m.id) || r.id || "",
        D10_um: r.d10!=null ? +r.d10.toFixed(1) : null,
        D50_um: r.d50!=null ? +r.d50.toFixed(1) : null,
        D90_um: r.d90!=null ? +r.d90.toFixed(1) : null,
        Mean_um: r.meanUm!=null ? +r.meanUm.toFixed(1) : null,
        Sorting: r.sortG!=null ? +r.sortG.toFixed(2) : null,
        Sorting_class: r.sortClass || "",
        Skewness: r.skewG!=null ? +r.skewG.toFixed(2) : null,
        Skewness_class: r.skewClass || "",
        Kurtosis: r.kurtG!=null ? +r.kurtG.toFixed(2) : null,
        Kurtosis_class: r.kurtClass || "",
        Notes: (m && m.notes) || "",
      };
    });
  },
  photos:   arr => (arr||[]).map(r => ({Top_Depth:r.top, Base_Depth:r.base, Filename:r.file, Caption:r.cap})),
  uvphotos: arr => (arr||[]).map(r => ({Top_Depth:r.top, Base_Depth:r.base, Filename:r.file, Caption:r.cap})),
  ctimages: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, Filename:r.file,
    Contrast_Min:r.cmin, Contrast_Max:r.cmax, Caption:r.cap,
  })),
  ctthumbs: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base, Filename:r.file, Caption:r.cap,
  })),
  sem: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base,
    // Join the per-row file list back into a single semicolon-
    // separated string for the workbook column. The parser accepts
    // ; | newlines so any of those round-trip cleanly.
    Filenames:(r.files||[]).join("; "),
    Magnification:r.mag,
    Caption:r.cap,
  })),
  tsphotos: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base,
    // Join the per-interval file list back into a single semicolon-
    // separated string for the workbook column. The parser accepts
    // ; | newlines so any of those round-trip cleanly.
    Filenames:(r.files||[]).join("; "),
    Magnification:r.mag,
    Caption:r.cap,
  })),
  ichnophotos: arr => (arr||[]).map(r => ({
    Top_Depth:r.top, Base_Depth:r.base,
    Filenames:(r.files||[]).join("; "),
    Magnification:r.mag,
    Caption:r.cap,
  })),
  descriptions: arr => (arr||[]).map(r => ({Top_Depth:r.top, Base_Depth:r.base, Description:r.text})),
};

function binDehydrate(arr, bins){
  return (arr||[]).map(r => {
    const o = {Depth:r.d, Sample_ID:r.id};
    (bins||[]).forEach(b => { o[b.key] = r.vals ? (r.vals[b.key] || 0) : 0; });
    return o;
  });
}

/* Shared row→state mapper for all three stratigraphy standards. */
function _hydrateStrat(rows){
  return (rows||[])
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      system:r.System||"", series:r.Series||"",
      stage:r.Stage||"",
      fm:r.Formation||"", mb:r.Member||"",
      index: strTrim(r.Index) || (typeof STAGE_INDEX !== "undefined" ? (STAGE_INDEX[strTrim(r.Stage)] || "") : ""),
      color: r.Color || null, notes: r.Notes || "",
    }));
}

/* ---------- HYDRATORS ----------
   Inverse of the dehydrators. Edited rows → state.<key>[] in normalised
   shape. Mirrors parseWorkbook() so the renderer reads the result. */
const SHEET_HYDRATE = {
  /* Well_Info: {Field, Value}[] → {Field: Value} object. Numeric
     fields (Core_Top, Core_Base, Latitude, Longitude, KB/GL elevations,
     WD, TVD/MD totals) are coerced to numbers when they parse cleanly;
     dates and free text stay as strings. Empty values are dropped from
     the resulting object so getters like state.wellInfo.Field stay
     `undefined` rather than empty string. */
  wellInfo: rows => {
    const NUMERIC_FIELDS = new Set([
      "Core_Top","Core_Base","Latitude","Longitude",
      "KB_Elevation","GL_Elevation","WD","TVD_Total","MD_Total",
    ]);
    const out = {};
    rows.forEach(r => {
      const k = strTrim(r.Field);
      if (!k) return;
      const raw = r.Value;
      if (raw == null || raw === "") return;
      if (NUMERIC_FIELDS.has(k)){
        const v = +String(raw).trim();
        out[k] = Number.isFinite(v) ? v : raw;
      } else {
        out[k] = raw;
      }
    });
    return out;
  },
  /* Stratigraphy hydrators — one per standard table, all sharing the same
     row→state shape via _hydrateStrat(). Auto-derives a blank Index from
     the Stage name through the shared STAGE_INDEX lookup (which now covers
     every standard's stages). */
  stratIcs: rows => _hydrateStrat(rows),
  stratRu:  rows => _hydrateStrat(rows),
  stratNa:  rows => _hydrateStrat(rows),
  biostrat: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      zone:r.Zone||"", group:r.Fossil_Group||"",
      species:r.Marker_Species||"", conf:r.Confidence||"", notes:r.Notes||"",
    })),
  geochron: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      age:numOrNull(r.Age_Ma), err:numOrNull(r.Age_Error_Ma),
      method:r.Method||"", material:r.Material||"", notes:r.Notes||"",
    })),
  cycles: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      name:r.Cycle||r.Name||"",
      trend:String(r.Trend||"").trim().toLowerCase().replace(/[\s-]+/g,"_"),
      comments:r.Comments||r.Notes||"",
      boundary:r.Boundary||"",
      surface:String(r.Surface_Type||"").trim(),
    }))
    .sort((a,b) => a.top - b.top),
  /* WaterLevel editor returns ONLY manual rows. After the editor saves,
     applyAll() calls rebuildWaterLevel() to re-merge the user-edited
     overrides with the freshly-auto-computed eustatic curve. */
  waterLevel: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth)
              && Number.isFinite(+r.Sea_Level_m))
    .map(r => ({
      top: +r.Top_Depth, base: +r.Base_Depth, wl: +r.Sea_Level_m,
      notes: r.Notes||"", src:"manual",
    })),
  /* MIS Temperature editor — same pattern as waterLevel: return only
     manual rows. applyAll() calls rebuildMisTemp() afterward to merge
     these with the freshly-auto-built per-stratigraphy curve. */
  misTemp: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth)
              && Number.isFinite(+r.Temperature_C))
    .map(r => ({
      top: +r.Top_Depth, base: +r.Base_Depth, temp: +r.Temperature_C,
      notes: r.Notes||"", src:"manual",
    })),
  systract: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      tract: strTrim(r.Tract).toUpperCase(),
      ps:r.Parasequence_Set||"", notes:r.Notes||"",
    })),
  coreRuns: rows => {
    const arr = rows
      .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
      .map(r => ({
        num: +r.Core_Num || 0,
        top:+r.Top_Depth, base:+r.Base_Depth,
        rec: numOrNull(r.Recovery_pct) ?? 100,
        notes:r.Notes||"",
      })).sort((a,b) => a.top - b.top);
    /* Recompute gaps[] — same logic as parseWorkbook */
    state.gaps = [];
    for (let i = 0; i < arr.length; i++){
      const c = arr[i], L = c.base - c.top;
      if (c.rec < 100 && L > 0){
        const missing = L * (1 - c.rec/100);
        if (missing > 0.02) state.gaps.push({top: c.base - missing, base: c.base, core: c.num});
      }
      const next = arr[i+1];
      if (next && next.top - c.base > 0.02){
        state.gaps.push({top: c.base, base: next.top, core: c.num + "–" + next.num});
      }
    }
    return arr;
  },
  lithology: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => {
      // Strip "CODE — Name" → just CODE for each column independently.
      // The editor's vocab cells store "code — name" so the user sees
      // the rock name inline; canonical state holds the bare code.
      const stripCode = v => strTrim(v).split(/\s+[—–-]\s+/)[0].toUpperCase();
      // Legacy single-column workbooks: fall back to the old `Lithology`
      // column and route the value into Lithology_FGDC (pre-existing
      // workbooks used FGDC codes / aliases — see workbook loader).
      const fgdc = stripCode(r.Lithology_FGDC || r.Lithology);
      const gost = stripCode(r.Lithology_GOST);
      const core = stripCode(r.Core_Lithology);
      return {
        top:+r.Top_Depth, base:+r.Base_Depth,
        lithFgdc: fgdc, lithGost: gost, lithCore: core,
        // Mirror the active-standard code into the legacy `lith` field so
        // any forgotten caller (or older save state) still works. Reads
        // should go through activeLithCode(row).
        lith: (state.symbolStyle === "gost" && gost) ? gost : (fgdc || gost),
        gs: strTrim(r.Grain_Size).toLowerCase(),
        sorting:r.Sorting, rounding:r.Rounding, colour:r.Colour,
        structures: String(r.Structures||"").split(/[,;|]/).map(s => s.trim().toLowerCase()).filter(Boolean),
        impurities: String(r.Impurities||"").split(/[,;|]/).map(s=>s.trim()).filter(Boolean),
        thinInterbeds: String(r.Thin_Interbeds||"").split(/[,;|]/).map(s=>s.trim().toLowerCase()).filter(Boolean),
        topBoundary: strTrim(r.Top_Boundary).toLowerCase(),
        desc:r.Short_Desc||"",
      };
    }),
  thinInterbeds: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r=>({d:+r.Depth,type:strTrim(r.Type||r.Thin_Interbed).toLowerCase(),notes:r.Notes||""}))
    .filter(r=>CORE_THIN_INTERBEDS[r.type]),
  impurities: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r=>({d:+r.Depth,type:canonicalImpurityKey(r.Impurity||r.Type),notes:r.Notes||""}))
    .filter(r=>CORE_IMPURITIES[r.type]),
  structures: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, code: strTrim(r.Structure).toLowerCase(), importance:strTrim(r.Importance).toLowerCase()||"primary",
      dip:numOrNull(r.Dip_Angle), note:r.Notes||"",
    })),
  faunal: rows => rows.filter(r=>Number.isFinite(+r.Depth)).map(r=>({d:+r.Depth,type:strTrim(r.Type).toLowerCase(),taxon:r.Taxon||"",abund:numOrNull(r.Abundance),preservation:r.Preservation||"",notes:r.Notes||""})),
  biot: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      bi: Math.max(0, Math.min(6, Math.round(numOrNull(r.BI) ?? 0))),
      notes:r.Notes||"",
    })),
  ichno: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, taxa: strTrim(r.Ichnotaxa),
      facies: strTrim(r.Ichnofacies) || "—",
      abund: numOrNull(r.Abundance), notes:r.Notes||"",
    })),
  plants: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, type: strTrim(r.Type).toLowerCase() || "debris",
      abund: numOrNull(r.Abundance), notes:r.Notes||"",
    })),
  roots: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({d:+r.Depth, type:strTrim(r.Type).toLowerCase()||"root", density: numOrNull(r.Density), notes:r.Notes||""})),
  env: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      name: strTrim(r.Environment) || "—",
      code: r.Facies_Code || "", notes:r.Notes||"",
    })),
  paleocurrent: rows => rows
    .filter(r => Number.isFinite(+r.Depth) && r.Azimuth != null && r.Azimuth !== "")
    .map(r => ({
      d:+r.Depth, azim:numOrNull(r.Azimuth), dip:numOrNull(r.Dip),
      count:numOrNull(r.Count), structure:r.Structure||"", notes:r.Notes||"",
    })),
  hcshows: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, intensity: numOrNull(r.Intensity),
      type: strTrim(r.Type).toLowerCase(),
      fluor:r.Fluorescence||"", cut:r.Cut||"", notes:r.Notes||"",
    })),
  gamma: rows => rows
    .filter(r => Number.isFinite(+r.Depth) && Number.isFinite(+r.GR_API))
    .map(r => ({d:+r.Depth, gr:+r.GR_API}))
    .sort((a,b) => a.d - b.d),
  spectral: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, k:numOrNull(r.K_pct), u:numOrNull(r.U_ppm), th:numOrNull(r.Th_ppm),
    })).sort((a,b) => a.d - b.d),
  ctdensity: rows => rows
    .filter(r => Number.isFinite(+r.Depth) && r.RhoB_gcc != null && r.RhoB_gcc !== "")
    .map(r => ({d:+r.Depth, rhob: numOrNull(r.RhoB_gcc)}))
    .sort((a,b) => a.d - b.d),
  magsus: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, ms:numOrNull(r.MagSus_SI_e6),
      dec:numOrNull(r.Declination), inc:numOrNull(r.Inclination),
      pol: strTrim(r.Polarity).toUpperCase(), notes:r.Notes||"",
    })).sort((a,b) => a.d - b.d),
  rca: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, id:r.Sample_ID,
      phi:numOrNull(r.Porosity_pct), k:numOrNull(r.Permeability_mD),
      rho:numOrNull(r.Grain_Density), note:r.Notes||"",
    })),
  saturations: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({d:+r.Depth, so:numOrNull(r.So), sg:numOrNull(r.Sg), sw:numOrNull(r.Sw)}))
    .sort((a,b) => a.d - b.d),
  archie: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, id:r.Sample_ID||"",
      m:numOrNull(r.m_exponent), n:numOrNull(r.n_exponent),
      swi:numOrNull(r.Swi_pct), notes:r.Notes||"",
    })),
  scal: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, id:r.Sample_ID||"",
      swi:numOrNull(r.Swi_pct), sor:numOrNull(r.Sor_pct),
      kro:numOrNull(r.kro_at_Swi), cross:numOrNull(r.Sw_crossover),
      system:r.System||"", notes:r.Notes||"",
    })),
  fractures: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      dens:numOrNull(r.Density_per_m), azim:numOrNull(r.Mean_Azimuth),
      dip:numOrNull(r.Mean_Dip), setName:r.Set_Name||"", notes:r.Notes||"",
    })),
  sourcerock: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, toc:numOrNull(r.TOC_pct), ro:numOrNull(r.Ro_pct),
      tmax:numOrNull(r.Tmax_C),
      s1:numOrNull(r.S1_mgHCgRock), s2:numOrNull(r.S2_mgHCgRock),
      s3:numOrNull(r.S3_mgCO2gRock),
      hi:numOrNull(r.HI), oi:numOrNull(r.OI), pi:numOrNull(r.PI),
      kerogen:r.Kerogen_Type||"", notes:r.Notes||"",
    })).sort((a,b) => a.d - b.d),
  xrd: (rows, sheet) => {
    const cols = sheet ? sheet.workingCols : null;
    let mineralKeys;
    if (cols && cols.length){
      mineralKeys = cols.filter(c => c.key !== "Depth").map(c => c.key);
    } else {
      const set = new Set();
      rows.forEach(r => Object.keys(r).forEach(k => { if (k !== "Depth") set.add(k); }));
      mineralKeys = [...set];
    }
    const data = rows
      .filter(r => Number.isFinite(+r.Depth))
      .map(r => {
        const o = {d:+r.Depth, vals:{}};
        mineralKeys.forEach(k => { o.vals[k] = numOrNull(r[k]) || 0; });
        return o;
      }).sort((a,b) => a.d - b.d);
    state.xrdCols = mineralKeys;
    return data;
  },
  nmr:        (rows, sheet) => hydrateBinSheet(rows, sheet, "nmrBins", true),
  micppsd:    (rows, sheet) => hydrateBinSheet(rows, sheet, "micppsdBins", false),
  centrifuge: (rows, sheet) => hydrateBinSheet(rows, sheet, "centrifugeBins", false),
  gs:         (rows, sheet) => hydrateBinSheet(rows, sheet, "gsBins", false),
  gsstats: rows => rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => ({
      d:+r.Depth, id: strTrim(r.Sample_ID),
      d10:numOrNull(r.D10_um), d50:numOrNull(r.D50_um), d90:numOrNull(r.D90_um),
      mean:numOrNull(r.Mean_um), sort:numOrNull(r.Sorting),
      skew:numOrNull(r.Skewness), kurt:numOrNull(r.Kurtosis),
      notes: r.Notes||"",
    })).sort((a,b) => a.d - b.d),
  photos: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({top:+r.Top_Depth, base:+r.Base_Depth, file: strTrim(r.Filename), cap:r.Caption||""})),
  uvphotos: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({top:+r.Top_Depth, base:+r.Base_Depth, file: strTrim(r.Filename), cap:r.Caption||""})),
  ctimages: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      file: strTrim(r.Filename), cap:r.Caption||"",
      cmin:numOrNull(r.Contrast_Min), cmax:numOrNull(r.Contrast_Max),
    })),
  // CT Thumbs: same shape as Photos/UVPhotos (interval + single file).
  // This hydrator was missing, which made "Apply" on the CT Thumbs sheet
  // fail with "No hydrator for sheet ctthumbs" — newly-added rows in the
  // editor couldn't be committed to state. Mirrors the workbook loader
  // for state.ctthumbs exactly.
  ctthumbs: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({top:+r.Top_Depth, base:+r.Base_Depth, file: strTrim(r.Filename), cap:r.Caption||""})),
  // SEM: multi-image-per-row. The Filenames column holds a ;/|/newline-
  // separated list; split + trim into a `files` array (matching the
  // workbook loader for state.sem). Backward-compat: accept a singular
  // Filename too. Rows with no usable filename are dropped. This
  // hydrator was missing, so "Apply" on the SEM sheet errored out.
  sem: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      files: String(r.Filenames || r.Filename || "")
        .split(/[;|\n\r]+/).map(s => s.trim()).filter(Boolean),
      cap:r.Caption||"",
      mag:r.Magnification||"",
    }))
    .filter(r => r.files.length),
  // Thin sections: multi-image-per-interval, mirroring SEM. The Filenames
  // column holds a ;/|/newline-separated list; split + trim into a `files`
  // array. Rows without a usable interval or filename are dropped.
  tsphotos: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      files: String(r.Filenames || "")
        .split(/[;|\n\r]+/).map(s => s.trim()).filter(Boolean),
      mag:r.Magnification||"",
      cap:r.Caption||"",
    }))
    .filter(r => r.files.length),
  ichnophotos: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({
      top:+r.Top_Depth, base:+r.Base_Depth,
      files: String(r.Filenames || "")
        .split(/[;|\n\r]+/).map(s => s.trim()).filter(Boolean),
      mag:r.Magnification||"",
      cap:r.Caption||"",
    }))
    .filter(r => r.files.length),
  descriptions: rows => rows
    .filter(r => Number.isFinite(+r.Top_Depth) && Number.isFinite(+r.Base_Depth))
    .map(r => ({top:+r.Top_Depth, base:+r.Base_Depth, text: String(r.Description||"")})),
};

function hydrateBinSheet(rows, sheet, binsKey, isNmr){
  const cols = (sheet && sheet.workingCols) || [];
  const binCols = cols.filter(c => c.key !== "Depth" && c.key !== "Sample_ID" && c.key !== "Notes");
  const bins = binCols.map(c => {
    const v = +String(c.key).trim();
    return Number.isFinite(v) && v > 0 ? {key:c.key, x:v} : null;
  }).filter(Boolean).sort((a,b) => a.x - b.x);
  const data = rows
    .filter(r => Number.isFinite(+r.Depth))
    .map(r => {
      const vals = {};
      binCols.forEach(c => { vals[c.key] = numOrNull(r[c.key]) || 0; });
      return {d:+r.Depth, id:r.Sample_ID||"", vals};
    }).sort((a,b) => a.d - b.d);
  if (isNmr){
    state[binsKey] = bins.map(b => ({key:b.key, ms:b.x}));
  } else {
    state[binsKey] = bins;
  }
  return data;
}

